+function FormField({ id, label, type, required, autoComplete, helpText, value, error, onChange, onBlur, inputRef }) {
+  const helpId = helpText ? `${id}-help` : null;
+  const errorId = `${id}-error`;
+  const describedBy = [helpId, error ? errorId : null].filter(Boolean).join(" ") || undefined;
+
+  return (
+    <div className="form-field">
+      <label htmlFor={id}>
+        {label}
+        {required ? <span className="req-marker" aria-hidden="true">*</span> : null}
+      </label>
+      <input
+        ref={inputRef}
+        id={id}
+        name={id}
+        type={type}
+        value={value}
+        required={required || undefined}
+        autoComplete={autoComplete}
+        aria-describedby={describedBy}
+        aria-invalid={error ? "true" : undefined}
+        onChange={(e) => onChange(e.target.value)}
+        onBlur={onBlur}
+      />
+      {helpText ? <p id={helpId} className="help-text">{helpText}</p> : null}
+      {error ? <p id={errorId} className="error-text">Error: {error}</p> : null}
+    </div>
+  );
+}
+
+function validate(values) {
+  const errors = {};
