const fs = require('fs');
const path = require('path');
const axeSource = fs.readFileSync(require.resolve('axe-core/axe.min.js'), 'utf8');

(async () => {
  const html = fs.readFileSync(path.join(__dirname, 'index.html'), 'utf8');
  const dom = await JSDOM.fromURL('http://localhost:8765/index.html', {
    runScripts: 'dangerously',
    resources: 'usable',
    pretendToBeVisual: true,
  });
  const { window } = dom;
  // Wait for React to mount
  await new Promise((resolve, reject) => {
    const start = Date.now();
    const check = () => {
      if (window.document.querySelector('#fullName')) return resolve();
      if (Date.now() - start > 15000) return reject(new Error('React did not mount: ' + window.document.body.innerHTML.slice(0,400)));
      setTimeout(check, 200);
    };
    window.addEventListener('load', check);
    check();
  });

  // Inject axe
  const s = window.document.createElement('script');
  s.textContent = axeSource;
  window.document.head.appendChild(s);

  const runAxe = async (label) => {
    const results = await window.axe.run(window.document, {
      runOnly: { type: 'tag', values: ['wcag2a','wcag2aa','wcag21a','wcag21aa','wcag22aa','best-practice'] }
    });
    console.log(`\n=== ${label} === violations: ${results.violations.length}`);
    for (const v of results.violations) {
      console.log(`- [${v.impact}] ${v.id}: ${v.help}`);
      for (const n of v.nodes) console.log(`    ${n.target.join(' ')}\n      ${n.failureSummary.replace(/\n/g,' | ')}`);
    }
  };

  await runAxe('Initial');

  // Empty submit
  window.document.querySelector('button[type="submit"]').click();
  await new Promise(r => setTimeout(r, 300));
  await runAxe('After empty submit');

  // Fill invalid values
  const setVal = (id, v) => {
    const el = window.document.getElementById(id);
    const setter = Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, 'value').set;
    setter.call(el, v);
    el.dispatchEvent(new window.Event('input', { bubbles: true }));
    el.dispatchEvent(new window.Event('blur', { bubbles: true }));
  };
  setVal('fullName', 'Jane Doe');
  setVal('email', 'not-an-email');
  setVal('phone', 'abc');
  await new Promise(r => setTimeout(r, 100));
  window.document.querySelector('button[type="submit"]').click();
  await new Promise(r => setTimeout(r, 300));
  await runAxe('After invalid submit');

  dom.window.close();
})().catch(e => { console.error(e); process.exit(1); });
